"""H705: train-only early-layer spectral floors before sparse-rotation pilot."""
import torch,json,time,hashlib
from pathlib import Path
from run_bilin18_diverse_causal_tasks import ROOT,ART
STEM='bilin18_early_rotation_spectra'
def main():
 torch.set_num_threads(6);start=time.time();paths={'data':ART/'bilin18_early_bsf_data_captures.pt','manifest':ART/'bilin18_early_bsf_data_manifest.json','bsf':ART/'bilin18_early_bsf_extended.json','runner':Path(__file__)};hashes={k:hashlib.sha256(p.read_bytes()).hexdigest() for k,p in paths.items()};cfg=dict(experiment='H705',hashes=hashes,design='Fit training mean and centered covariance on H681 first2048documents (32768vectors/site), eigendecompose float64. Evaluate projection loss on next256validation documents only. Report ranks32/64/128/256/512/768/1024/1152, whitening condition, and historical H683 signedBSF references. No rotation or group fitting yet.',limitations='Validation repeatedly explored, reserved256documenttest untouched. PCA floor is fixed-linear-span reconstruction, not a fairness comparison with adaptive overcomplete BSFs. Centered float64 statistics differ slightly from H683float32 normalization. No new model forwards.')
 (ROOT/f'configs/{STEM}.json').write_text(json.dumps(cfg,indent=2));data=torch.load(paths['data'],weights_only=False);baseline=json.loads(paths['bsf'].read_text());records=[];states={}
 for site in ['value0','residual0','residual1','residual2']:
  raw=data['activations'][site];train=raw[:2048].reshape(-1,1152).cuda().double();val=raw[2048:2304].reshape(-1,1152).cuda().double();mu=train.mean(0);train-=mu;val-=mu;cov=train.T@train/len(train);eig,V=torch.linalg.eigh(cov);eig=eig.flip(0);V=V.flip(1);assert eig[-1]>0;total=float(eig.sum());cum=eig.cumsum(0)/eig.sum();z=val@V;venergy=val.square().sum();vparts=z.square().sum(0).cumsum(0);ranks=[]
  for k in [32,64,128,256,512,768,1024,1152]:ranks.append(dict(rank=k,training_variance_fraction=float(cum[k-1]),validation_projection_relative_mse=max(0.,float(1-vparts[k-1]/venergy)),retained_eigenvalue_condition=float(eig[0]/eig[k-1]),whitening_scale_ratio=float((eig[0]/eig[k-1]).sqrt())))
  thresholds={str(t):int(torch.searchsorted(cum,torch.tensor(t,device='cuda',dtype=torch.float64)))+1 for t in [.5,.75,.9,.95,.99]};refs=[]
  for blockdim in [1,4,16]:
   rr=[r for r in baseline['records'] if r['site']==site and r['block_dimension']==blockdim];err=sum(r['validation_relative_mse'] for r in rr)/len(rr);minimum=next((k+1 for k,e in enumerate((1-vparts/venergy).tolist()) if e<=err),None);refs.append(dict(block_dimension=blockdim,mean_validation_relative_mse=err,minimum_pca_rank_to_reach_that_error=minimum,active_scalars=32,decoder_atoms=2304))
  orth=float((V.T@V-torch.eye(1152,device='cuda',dtype=torch.float64)).abs().max());whitening=(train@V[:,:128])/eig[:128].sqrt();whiteningerr=float((whitening.T@whitening/len(train)-torch.eye(128,device='cuda',dtype=torch.float64)).abs().max());direct=float((val-(val@V[:,:128])@V[:,:128].T).square().sum()/venergy);assert abs(direct-ranks[2]['validation_projection_relative_mse'])<1e-10 and orth<1e-10 and whiteningerr<1e-10
  rec=dict(site=site,training_vectors=len(train),validation_vectors=len(val),mean_norm=float(mu.norm()),centered_energy_per_vector=total,rank_thresholds=thresholds,ranks=ranks,bsf_references=refs,orthogonality_error=orth,whitening_128_error=whiteningerr);records.append(rec);states[site]=dict(mean=mu.cpu(),eigenvalues=eig.cpu(),eigenvectors=V.cpu());print(rec,flush=True);del train,val,cov,z,whitening
 audits=dict(hashes_unchanged={k:hashlib.sha256(p.read_bytes()).hexdigest()==hashes[k] for k,p in paths.items()},finite=all(torch.isfinite(torch.tensor(r['centered_energy_per_vector'])).item() for r in records),test_evaluations=0,whole_model_forwards=0);assert all(audits['hashes_unchanged'].values()) and audits['finite'];torch.save(dict(states=states),ART/f'{STEM}_captures.pt');(ART/f'{STEM}.json').write_text(json.dumps(dict(status='complete',config=cfg,records=records,audits=audits,elapsed_seconds=time.time()-start),indent=2));print(audits,flush=True)
if __name__=='__main__':main()
